#include<iostream>
#include<cstring>
#include<queue>
#include<map>
#include<cmath>
#include<cstdio>
#include<vector>
#include<climits>
using namespace std;

const int MAX_M = 1000007;
const int MAX_N = 210;
typedef long long ll;

char grid1[15][15], grid2[15][15];
int node_id[15][15], node_count;
int source, sink, max_time, size_n;
int zero_x, zero_y;
const int dx[4] = {0, 0, 1, -1};
const int dy[4] = {1, -1, 0, 0};

bool is_valid(int x, int y) {
    return x >= 0 && y >= 0 && x < size_n && y < size_n && grid1[x][y] >= '0' && grid1[x][y] <= '9';
}

struct Edge {
    int to, capacity, reverse_edge;
    Edge(int t, int c, int r) : to(t), capacity(c), reverse_edge(r) {}
};

vector<Edge> edges[MAX_N * 2];
int dist[MAX_N], ptr[MAX_N];

void add_edge(int u, int v, int cap) {
    edges[u].emplace_back(v, cap, edges[v].size());
    edges[v].emplace_back(u, 0, edges[u].size() - 1);
}

void bfs_from(int x, int y) {
    if (grid2[x][y] != '\0') {
        add_edge(node_id[x][y] + node_count, sink, grid2[x][y] - '0');
    }
    if (grid1[x][y] == '0') return;

    add_edge(source, node_id[x][y], grid1[x][y] - '0');
    if (grid2[x][y] != '\0') {
        add_edge(node_id[x][y], node_id[x][y] + node_count, 10);
    }

    int start_x = x, start_y = y;
    queue<int> qx, qy;
    qx.push(x); qy.push(y);
    queue<int> qz_x, qz_y;
    qz_x.push(zero_x); qz_y.push(zero_y);

    vector<vector<int>> d1(size_n, vector<int>(size_n, -1));
    vector<vector<int>> d2(size_n, vector<int>(size_n, -1));
    d1[x][y] = 0;
    d2[zero_x][zero_y] = 0;

    while (!qx.empty()) {
        int sz1 = qx.size();
        for (int i = 0; i < sz1; ++i) {
            int cx = qx.front(); qx.pop();
            int cy = qy.front(); qy.pop();
            if (d2[cx][cy] >= 0) continue;
            for (int k = 0; k < 4; ++k) {
                int nx = cx + dx[k], ny = cy + dy[k];
                if (is_valid(nx, ny) && d1[nx][ny] == -1) {
                    d1[nx][ny] = d1[cx][cy] + 1;
                    if (d1[nx][ny] > max_time) break;
                    if (d2[nx][ny] >= 0) continue;
                    qx.push(nx); qy.push(ny);
                    if (grid2[nx][ny] != '0') {
                        add_edge(node_id[start_x][start_y], node_id[nx][ny] + node_count, 10);
                    }
                }
            }
        }

        int sz2 = qz_x.size();
        for (int i = 0; i < sz2; ++i) {
            int cx = qz_x.front(); qz_x.pop();
            int cy = qz_y.front(); qz_y.pop();
            for (int k = 0; k < 4; ++k) {
                int nx = cx + dx[k], ny = cy + dy[k];
                if (is_valid(nx, ny) && d2[nx][ny] == -1) {
                    d2[nx][ny] = d2[cx][cy] + 1;
                    qz_x.push(nx); qz_y.push(ny);
                }
            }
        }
    }
}

bool dinic_bfs() {
    memset(dist, -1, sizeof(dist));
    queue<int> q;
    q.push(source);
    dist[source] = 0;

    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (const auto& e : edges[u]) {
            if (e.capacity > 0 && dist[e.to] == -1) {
                dist[e.to] = dist[u] + 1;
                q.push(e.to);
            }
        }
    }
    return dist[sink] != -1;
}

int dinic_dfs(int u, int flow) {
    if (u == sink) return flow;
    for (int& i = ptr[u]; i < edges[u].size(); ++i) {
        auto& e = edges[u][i];
        if (e.capacity > 0 && dist[e.to] == dist[u] + 1) {
            int pushed = dinic_dfs(e.to, min(flow, e.capacity));
            if (pushed > 0) {
                e.capacity -= pushed;
                edges[e.to][e.reverse_edge].capacity += pushed;
                return pushed;
            }
        }
    }
    return 0;
}

int max_flow() {
    int result = 0;
    while (dinic_bfs()) {
        memset(ptr, 0, sizeof(ptr));
        while (int pushed = dinic_dfs(source, INT_MAX)) {
            result += pushed;
        }
    }
    return result;
}

int main() {
    cin >> size_n >> max_time;
    for (int i = 0; i < size_n; ++i) cin >> grid1[i];
    for (int i = 0; i < size_n; ++i) cin >> grid2[i];

    memset(node_id, -1, sizeof(node_id));
    node_count = 0;
    for (int i = 0; i < size_n; ++i) {
        for (int j = 0; j < size_n; ++j) {
            if (grid1[i][j] == 'Z') {
                zero_x = i; zero_y = j;
            } else if (is_valid(i, j)) {
                node_id[i][j] = ++node_count;
            }
        }
    }

    source = 0;
    sink = 2 * node_count + 1;

    for (int i = 0; i < size_n; ++i) {
        for (int j = 0; j < size_n; ++j) {
            if (is_valid(i, j)) {
                bfs_from(i, j);
            }
        }
    }

    cout << max_flow() << endl;
    return 0;
}
